require('dotenv').config();
const express = require('express');
const bodyParser = require('body-parser');
const path = require('path');
const fs = require('fs');
const winston = require('winston');

// Import services
const authService = require('./services/auth');
const webSubService = require('./services/websub');
const dataShareService = require('./services/dataShare');
const logger = require('./services/logger');

/**
 * SubSafe - MOSIP WebSub event listener with message decryption capabilities
 * @class SubSafe
 */
class SubSafe {
  /**
   * Create a new SubSafe instance
   * @param {Object} options - Configuration options
   */
  constructor(options = {}) {
    this.app = express();
    
    // Server configuration
    this.port = options.port || process.env.PORT || 3000;
    
    // Store event handlers
    this.eventHandlers = [];
    
    // Store callback URL
    this.callbackUrl = '';
    
    // Store current processing status
    this.currentStatus = 'idle';
    this.statusTimestamp = Date.now();
    this.statusHistory = [];
    
    // Set log level from options or environment
    if (options.logLevel || process.env.LOG_LEVEL) {
      logger.level = options.logLevel || process.env.LOG_LEVEL;
    }
    
    // Store last registration ID
    this.lastRegistrationId = null;
    
    logger.info('SubSafe instance initialized');
    
    // Update service configurations
    this._updateServiceConfigurations(options);
    
    // Initialize server
    this._initializeServer();
    
    // Set up websub event listeners
    this._setupWebSubListeners();
  }

  /**
   * Get system logs for UI display
   * @returns {Array} - Array of log entries
   */
  getLogs() {
    return logger.getLogHistory();
  }

  /**
   * Update configurations for all services
   * @private
   */
  _updateServiceConfigurations(options) {
    // Auth service configuration
    authService.updateConfig({
      baseUrl: options.baseUrl || process.env.MOSIP_BASE_URL,
      clientId: options.clientId || process.env.MOSIP_CLIENT_ID,
      secretKey: options.clientSecret || process.env.MOSIP_SECRET_KEY,
      authEndpoint: options.authEndpoint || process.env.MOSIP_AUTH_ENDPOINT,
      appId: options.appId || process.env.MOSIP_APP_ID,
      tokenUrl: options.tokenUrl || process.env.MOSIP_TOKEN_URL
    });
    
    // WebSub service configuration
    webSubService.updateConfig({
      hubUrl: options.hubUrl || process.env.MOSIP_WEBSUB_URL,
      topic: options.topic || process.env.MOSIP_TOPIC,
      callbackPath: options.callbackPath || process.env.CALLBACK_PATH || '/callback/notifyEvent',
      secret: options.secret || process.env.MOSIP_WEBSUB_SECRET,
      port: this.port
    });
    
    // DataShare service configuration
    dataShareService.updateConfig({
      mode: options.dataSourceMode || process.env.DATA_SOURCE_MODE || 'datashare',
      directMessagePath: options.directMessagePath || process.env.DIRECT_MESSAGE_PATH || 'event.data.credential',
      registrationIdField: options.registrationIdField || process.env.REGISTRATION_ID_FIELD || 'event.data.registrationId',
      dataShareBaseUrl: options.dataShareBaseUrl || process.env.DATASHARE_BASE_URL,
      decryption: {
        p12Path: options.p12Path || process.env.P12_PATH,
        p12Password: options.p12Password || process.env.P12_PASSWORD,
        tempEncryptedFile: options.tempEncryptedFile || process.env.TEMP_ENCRYPTED_FILE,
        tempDecryptedFile: options.tempDecryptedFile || process.env.TEMP_DECRYPTED_FILE
      }
    });
    
    logger.debug('Service configurations updated');
  }

  /**
   * Set up WebSub event listeners
   * @private
   */
  _setupWebSubListeners() {
    // Listen for status updates from WebSub service
    webSubService.on('status', (status) => {
      this._updateStatus(status);
    });
    
    // Listen for status updates from DataShare service
    dataShareService.on('status', (status) => {
      this._updateStatus(status);
    });
    
    webSubService.on('notification', async (notification) => {
      try {
        this._updateStatus('notification_received');
        logger.info('Received notification from WebSub hub');
        logger.debug('Notification payload', { payload: notification });
        
        // Extract registration ID from notification
        this.lastRegistrationId = dataShareService.extractValueByPath(
          notification, 
          dataShareService.config.registrationIdField
        );
        
        if (this.lastRegistrationId) {
          logger.info(`Processing notification for registration ID: ${this.lastRegistrationId}`);
        }
        
        // Process the notification using the DataShare service
        const decryptedData = await dataShareService.processNotification(notification);
        
        this._updateStatus('notification_processed');
        logger.info('Successfully processed notification');
        
        // Call all registered event handlers
        this.eventHandlers.forEach(handler => {
          try {
            handler(decryptedData, notification);
          } catch (handlerError) {
            logger.error('Error in notification handler', { error: handlerError.message });
          }
        });
      } catch (error) {
        logger.error('Error processing notification', { 
          error: error.message,
          stack: error.stack
        });
        this._updateStatus('notification_processing_error');
        
        // Call handlers with error information
        this.eventHandlers.forEach(handler => {
          try {
            handler({ error: error.message }, notification);
          } catch (handlerError) {
            logger.error('Error in notification handler', { error: handlerError.message });
          }
        });
      }
    });
    
    logger.debug('WebSub event listeners configured');
  }

  /**
   * Update the current status
   * @param {string} status - The new status
   * @private
   */
  _updateStatus(status) {
    const timestamp = Date.now();
    
    // Update current status
    this.currentStatus = status;
    this.statusTimestamp = timestamp;
    
    // Add to history (limited to last 10 entries)
    this.statusHistory.unshift({
      status,
      timestamp,
      time: new Date(timestamp).toISOString()
    });
    
    // Limit history to 10 entries
    if (this.statusHistory.length > 10) {
      this.statusHistory = this.statusHistory.slice(0, 10);
    }
    
    logger.info(`Status updated: ${status}`);
  }

  /**
   * Add event handler for notification events
   * @param {Function} handler - Event handler function that receives decrypted data
   * @returns {SubSafe} - this instance for method chaining
   */
  onNotification(handler) {
    if (typeof handler === 'function') {
      this.eventHandlers.push(handler);
      logger.debug('Added notification event handler');
    }
    return this;
  }

  /**
   * Initialize Express server and configure routes
   * @private
   */
  _initializeServer() {
    // Configure Express app
    this.app.use(bodyParser.json());
    
    // Serve static files from public directory
    this.app.use(express.static(path.join(__dirname, 'public')));
    
    // Set callback route for WebSub events
    this.app.use(webSubService.getRouter());
    
    // Dashboard route
    this.app.get('/', (req, res) => {
      res.sendFile(path.join(__dirname, 'public/index.html'));
    });
    
    // Status API endpoint
    this.app.get('/api/status', (req, res) => {
      const statusResponse = {
        // Server status
        status: this.currentStatus,
        timestamp: this.statusTimestamp,
        time: new Date(this.statusTimestamp).toISOString(),
        statusHistory: this.statusHistory,
        systemLogs: this.getLogs(),
        
        // WebSub configuration
        websub: {
          isSubscribed: webSubService.isSubscribed,
          hubUrl: webSubService.config.hubUrl,
          topic: webSubService.config.topic,
          callbackPath: webSubService.config.callbackPath,
          callbackUrl: this.callbackUrl
        },
        
        // DataShare configuration
        dataShare: {
          mode: dataShareService.config.mode,
          directMessagePath: dataShareService.config.directMessagePath,
          dataShareBaseUrl: dataShareService.config.dataShareBaseUrl,
          p12Configured: !!dataShareService.config.decryption.p12Path
        },
        
        // Registration ID tracking
        registrationIdField: dataShareService.config.registrationIdField,
        lastRegistrationId: this.lastRegistrationId
      };
      
      res.json(statusResponse);
    });
    
    // Log level API endpoint
    this.app.get('/api/log-level', (req, res) => {
      res.json({
        currentLevel: logger.level,
        availableLevels: Object.keys(winston.config.npm.levels)
      });
    });
    
    // Change log level API endpoint
    this.app.post('/api/log-level', bodyParser.urlencoded({ extended: true }), (req, res) => {
      const newLevel = req.body.level;
      
      if (newLevel && Object.keys(winston.config.npm.levels).includes(newLevel)) {
        logger.level = newLevel;
        logger.info(`Log level changed to ${newLevel}`);
        res.json({ success: true, level: newLevel });
      } else {
        res.status(400).json({ 
          success: false, 
          message: 'Invalid log level',
          availableLevels: Object.keys(winston.config.npm.levels)
        });
      }
    });
    
    // Subscribe endpoint
    this.app.get('/subscribe', async (req, res) => {
      try {
        await this.subscribe();
        res.send('Subscription request sent');
      } catch (error) {
        res.status(500).send('Subscription failed: ' + error.message);
      }
    });
    
    // Unsubscribe endpoint
    this.app.get('/unsubscribe', async (req, res) => {
      try {
        await this.unsubscribe();
        res.send('Unsubscription request sent');
      } catch (error) {
        res.status(500).send('Unsubscription failed: ' + error.message);
      }
    });
  }

  /**
   * Start the server and set the callback URL
   * @param {string} callbackUrl - The callback URL for WebSub notifications
   * @returns {Promise<http.Server>} - Express server instance
   */
  start(callbackUrl) {
    return new Promise((resolve, reject) => {
      try {
        // Set the callback URL
        this.callbackUrl = callbackUrl;
        
        // Update WebSub service with the callback URL
        webSubService.setCallbackUrl(this.callbackUrl);
        
        // Start the server
        const server = this.app.listen(this.port, () => {
          logger.info(`Server started on port ${this.port}`);
          
          // If AUTO_SUBSCRIBE is true, subscribe automatically
          if (process.env.AUTO_SUBSCRIBE === 'true') {
            this.subscribe()
              .then(() => {
                logger.info(`Callback URL set to: ${this.callbackUrl}`);
                resolve(server);
              })
              .catch(err => {
                logger.error('Auto-subscription failed', { error: err.message });
                resolve(server); // Resolve anyway to not block startup
              });
          } else {
            resolve(server);
          }
        });
        
        // Handle server errors
        server.on('error', (error) => {
          logger.error('Server error', { error: error.message });
          reject(error);
        });
      } catch (error) {
        logger.error('Error starting server', { error: error.message, stack: error.stack });
        reject(error);
      }
    });
  }
  
  /**
   * Subscribe to the WebSub hub
   * @returns {Promise<void>}
   */
  async subscribe() {
    try {
      await webSubService.subscribe();
      return true;
    } catch (error) {
      logger.error('Subscription failed', { error: error.message });
      throw error;
    }
  }
  
  /**
   * Unsubscribe from the WebSub hub
   * @returns {Promise<void>}
   */
  async unsubscribe() {
    try {
      await webSubService.unsubscribe();
      return true;
    } catch (error) {
      logger.error('Unsubscription failed', { error: error.message });
      throw error;
    }
  }

  /**
   * Get subscription status
   * @returns {boolean} - Whether the subscription is active
   */
  get isSubscribed() {
    return webSubService.isSubscribed;
  }
  
  /**
   * Set subscription status (mainly for testing)
   */
  set isSubscribed(value) {
    webSubService.isSubscribed = !!value;
  }
}

// Export the SubSafe class as the default export
module.exports = SubSafe;

// Also export the logger for convenience
module.exports.logger = require('./services/logger');

/**
 * Create a standalone SubSafe instance with default configuration
 */
if (require.main === module) {
  // Create a default instance
  const subsafe = new SubSafe();
  
  // Log startup information
  logger.info('SubSafe - MOSIP WebSub Client');
  
  // Add notification handler
  subsafe.onNotification((data) => {
    logger.info('Event received and processed!');
    logger.debug('Decrypted data', { data });
  });
  
  // Start the server with ngrok tunneling
  const callbackUrl = process.env.CALLBACK_URL;
  
  // Start the server
  subsafe.start(callbackUrl)
    .then(async () => {
      try {
        await subsafe.subscribe();
      } catch (error) {
        logger.error('Auto-subscription failed', { error: error.message });
      }
    })
    .catch(error => {
      logger.error('Failed to start SubSafe', { error: error.message });
      process.exit(1);
    });
} 